UPDATE ACA701  /* 긴급대응보고대상자 */
   SET TRPR_INFO_NO = #{TRPR_INFO_NO},        /* 대상자정보번호 */
       CASE_MNG_NO = #{CASE_MNG_NO},
       CASE_MNG_ODRNO = #{CASE_MNG_ODRNO},
       LAST_MDFR_ID = #{USER_ID},              /* 최종수정자아이디 */
       LAST_MDFCN_DT = SYSDATE                 /* 최종수정일시 */
 WHERE EMRG_CNTRMS_INCDNT_NO = #{EMRG_CNTRMS_INCDNT_NO}
 AND INCDNT_NO_SN = #{INCDNT_NO_SN}

